def game_score(points: str) -> str:
    labels = {0: "0", 1: "15", 2: "30", 3: "40"}
    a = 0
    b = 0
    for p in points:
        if p == "A":
            a += 1
        elif p == "B":
            b += 1
        else:
            continue
        if a >= 4 and a > b:
            return "Game A"
        if b >= 4 and b > a:
            return "Game B"
    if a >= 3 and b >= 3 and a == b:
        return "40-40"
    return f"{labels[min(a, 3)]}-{labels[min(b, 3)]}"
